const body = $input.first().json.body || $input.first().json || {};

const userMessage = body.message || body.query || body.prompt || body.chatInput || "";
const repoUrl = body.repoUrl || body.repository || body.url || "";
const contextData = body.context || body.summary || body.analysis || {};

// 1. Direct repo name passed from frontend payload
let repoName = body.repoName || body.name || body.full_name || body.fullName || "";

// 2. Extract from explicit repoUrl
if (!repoName && repoUrl) {
  repoName = repoUrl.split('/').slice(-2).join('/').replace(/\.git$/, '');
}

// 3. Extract from stringified context
const contextStr = typeof contextData === 'object' ? JSON.stringify(contextData) : String(contextData);

if (!repoName && contextStr) {
  const match = contextStr.match(/([a-zA-Z0-9_\-]+\/[a-zA-Z0-9_\-]+)/);
  if (match) {
    repoName = match[1].trim();
  }
}

// Default fallback if payload was completely empty
const finalRepoName = repoName || "dhanvithshetty-in/gitgrok";

const fullPrompt = `
You are GitGrok Chat, an expert AI assistant answering questions about software repositories.

CURRENT TARGET REPOSITORY:
- Name: ${finalRepoName}
- Context Details:
${contextStr}

USER QUESTION:
${userMessage}

INSTRUCTIONS:
1. When asked for the repository name or project name, explicitly state "${finalRepoName}".
2. Answer all user questions using the repository details provided above.
3. Keep responses concise and accurate.
`;

return [{
  json: {
    prompt: fullPrompt,
    userMessage: userMessage,
    repoUrl: repoUrl,
    repoName: finalRepoName,
    contextStr: contextStr
  }
}];

const raw = $input.first().json || {};
let chunkList = null;
if (Array.isArray(raw)) chunkList = raw;
else if (Array.isArray(raw.body)) chunkList = raw.body;
else {
  chunkList = Object.keys(raw)
    .filter(k => !isNaN(Number(k)) && raw[k] && typeof raw[k] === 'object')
    .map(k => raw[k]);
}
if (!Array.isArray(chunkList)) chunkList = [];

const bp = $("Build Chat Prompt").first().json || {};
const userMessage = bp.userMessage || "";
const repoUrl = bp.repoUrl || "";

let citedFiles = [];

if (chunkList.length === 0) {
  return [{
    json: {
      prompt: `You are GitGrok Chat, a helpful software engineering assistant.

The code for this repository (${repoUrl || 'the requested repository'}) has not been indexed yet.

Reply to the user with this exact guidance, concise: "This repository's code hasn't been indexed yet. Run a fresh analysis and wait a few seconds, then ask again."

User question: ${userMessage}`,
      citedFiles: [],
      notIndexed: true
    }
  }];
}

const contextBlock = chunkList
  .slice(0, 5)
  .map(c => `FILE: ${c.file_path}\n${String(c.chunk_text || '').slice(0, 2000)}`)
  .join('\n\n');

citedFiles = [...new Set(chunkList.map(c => c.file_path).filter(Boolean))].slice(0, 5);

return [{
  json: {
    prompt: `You are GitGrok Chat, a senior software engineer answering questions about a specific GitHub repository.

Relevant code chunks extracted from the repository source code (answer ONLY from these chunks, and cite the exact file path for every claim you make):

${contextBlock}

User question: ${userMessage}

Answer concisely and specifically. Reference the file paths in your answer. If the chunks have enough context, explain the relevant code. If they do not, say so honestly and tell the user what would be needed.`,
    citedFiles,
    notIndexed: false
  }
}];

const ai = $input.first().json || {};
const content = String(ai.output || ai.text || ai.message?.content || ai.reply || ai.response || "").trim();
const rag = $("Build RAG Prompt").first().json || {};

return [{
  json: {
    type: 'done',
    content,
    citedFiles: rag.citedFiles || [],
    notIndexed: rag.notIndexed || false
  }
}];
